Add Flutter to any web application > Lazy-load embedded views below the fold {: #lazy-load-embedded-views }

By default, `flutter_bootstrap.js` calls `_flutter.loader.load()` immediately,
which can compete with host HTML, CSS, and critical images during initial page
load.

When an embedded Flutter view sits below the fold or opens on interaction,
defer `_flutter.loader.load()` in a custom `web/flutter_bootstrap.js` file
by using an `IntersectionObserver` (or a `click` or `pointerenter` listener) to
protect initial Largest Contentful Paint (LCP):

```js title="web/flutter_bootstrap.js"
{{flutter_js}}
{{flutter_build_config}}

function initLazyFlutter() {
  const hostElement = document.getElementById('flutter_host');
  if (!hostElement) return;

  const observer = new IntersectionObserver(
    (entries) => {
      if (!entries.some((entry) => entry.isIntersecting)) return;
      observer.disconnect();

      _flutter.loader.load({
        config: { hostElement },
      });
    },
    // Start loading before the container scrolls into view.
    { rootMargin: '200px' },
  );

  observer.observe(hostElement);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initLazyFlutter, {
    once: true,
  });
} else {
  initLazyFlutter();
}
```

Web FAQ > How do I configure my cache headers?

```json
{
  "hosting": {
    "public": "build/web",
    "ignore": [
      "firebase.json",
      "**/.*",
      "**/node_modules/**",
      "**/*.map"
    ],
    "headers": [
      {
        "source": "**",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "max-age=0, must-revalidate"
          }
        ]
      },
      {
        "source": "assets/**",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "public, max-age=31536000, immutable"
          }
        ]
      },
      {
        "source": "main.dart.*.+(js|wasm|mjs)",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "public, max-age=31536000, immutable"
          }
        ]
      },
      {
        "source": "404.html",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "max-age=0, must-revalidate"
          }
        ]
      }
    ],
    "rewrites": [
      {
        "source": "!(/assets/**|/canvaskit/**|/icons/**|/main.dart.*)",
        "destination": "/index.html"
      }
    ]
  }
}
```

If you build without `--web-content-hash`, omit the `immutable` rules for
`assets/**` and `main.dart.*.+(js|wasm|mjs)` so that all files revalidate via
`"source": "**"` and `"source": "404.html"` (`max-age=0, must-revalidate`),
receiving fast `304 Not Modified` responses from the CDN edge when unchanged.

